  for await (const t of ticks(2)) console.log('tick', t);

  const ee = new EventEmitter();
  setTimeout(() => ee.emit('ready', 'db'), 10);
  const [name] = await once(ee, 'ready');
  console.log('ready:', name);

  setTimeout(() => { ee.emit('msg', 'hi'); ee.emit('msg', 'bye'); }, 10);
  for await (const [text] of on(ee, 'msg')) {
    console.log('msg:', text);
    if (text === 'bye') break;
  }
  console.log('listeners left:', ee.listenerCount('msg'));
}
