const { setTimeout: sleep } = require('node:timers/promises');

async function retry(fn, {
  retries = 4,             // retries after the first try
  base = 100,              // ms
  max = 5_000,             // cap per wait
  shouldRetry = isTransient,
  signal,
} = {}) {
  for (let attempt = 0; ; attempt++) {
    try {
      return await fn({ attempt, signal });
    } catch (err) {
      if (attempt >= retries || !shouldRetry(err) || signal?.aborted) throw err;
      const exp = Math.min(max, base * 2 ** attempt);
      const delay = Math.random() * exp;          // "full jitter"
      await sleep(delay, undefined, { signal });
    }
  }
}

function isTransient(err) {
  if (['ECONNRESET', 'ETIMEDOUT', 'ECONNREFUSED', 'EAI_AGAIN'].includes(err.code)) return true;
  if (err.name === 'TimeoutError') return true;
  return [429, 502, 503, 504].includes(err.status);
}

